/* Pixel Focus Log - styles */
:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --primary: #6c63ff;
  --primary-hover: #5a52d5;
  --text: #e0e0f0;
  --text-muted: #a0a0c0;
  --border: #3f3f5a;
  --danger: #ff6b6b;
  --danger-hover: #e05555;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 520px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  margin: 0 0 4px;
  font-size: 1.75rem;
  font-weight: 700;
}

.subtitle {
  margin: 0 0 24px;
  color: var(--text-muted);
  font-size: 1rem;
}

.log-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 24px;
}

.field-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

label {
  font-weight: 600;
  font-size: 0.95rem;
}

input[type="text"],
input[type="number"] {
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #202033;
  color: var(--text);
  font-family: inherit;
  font-size: 1rem;
  transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(108, 99, 255, 0.3);
}

.btn {
  padding: 12px 20px;
  border: none;
  border-radius: 8px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.98);
}

.btn.primary {
  background: var(--primary);
  color: #fff;
}

.btn.primary:hover {
  background: var(--primary-hover);
}

.btn.delete {
  background: transparent;
  color: var(--danger);
  border: 1px solid var(--danger);
  padding: 6px 12px;
  font-size: 0.85rem;
  border-radius: 6px;
}

.btn.delete:hover {
  background: var(--danger);
  color: #fff;
}

.entries-section {
  margin-bottom: 24px;
}

h2 {
  font-size: 1.25rem;
  margin: 0 0 12px;
}

.entries-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.entry-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: #202033;
  padding: 12px 16px;
  border-radius: 8px;
  border: 1px solid var(--border);
}

.entry-text {
  flex: 1;
  word-break: break-word;
}

.entry-minutes {
  font-weight: 600;
  color: var(--primary);
  white-space: nowrap;
}

.empty-message {
  color: var(--text-muted);
  font-style: italic;
  margin: 0;
  padding: 8px 0;
}

.summary {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  border-top: 1px solid var(--border);
  padding-top: 16px;
}

.summary-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.summary-label {
  font-size: 0.85rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.summary-value {
  font-size: 1.5rem;
  font-weight: 700;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .summary {
    flex-direction: column;
    gap: 12px;
  }
  .entry-item {
    flex-wrap: wrap;
  }
}

'use strict';

(function() {
  const STORAGE_KEY = 'pixelFocusLog';

  // DOM elements
  const form = document.getElementById('log-form');
  const taskInput = document.getElementById('task-input');
  const minutesInput = document.getElementById('minutes-input');
  const entriesList = document.getElementById('entries-list');
  const emptyMessage = document.getElementById('empty-message');
  const totalEl = document.getElementById('total-minutes');
  const longestEl = document.getElementById('longest-session');

  // State: array of { id, task, minutes }
  let entries = [];

  // Load from localStorage
  function loadEntries() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const data = JSON.parse(raw);
        if (Array.isArray(data)) {
          entries = data.filter(e => e && typeof e.task === 'string' && typeof e.minutes === 'number');
        }
      }
    } catch (e) {
      // ignore corrupt data
    }
  }

  // Save to localStorage
  function saveEntries() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(entries));
    } catch (e) {
      // ignore quota errors
    }
  }

  // Generate unique ID
  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
  }

  // Render entries list
  function render() {
    entriesList.innerHTML = '';
    if (entries.length === 0) {
      emptyMessage.hidden = false;
    } else {
      emptyMessage.hidden = true;
      entries.forEach(entry => {
        const li = document.createElement('li');
        li.className = 'entry-item';
        li.dataset.id = entry.id;

        const spanText = document.createElement('span');
        spanText.className = 'entry-text';
        spanText.textContent = entry.task;

        const spanMin = document.createElement('span');
        spanMin.className = 'entry-minutes';
        spanMin.textContent = entry.minutes + ' min';

        const delBtn = document.createElement('button');
        delBtn.type = 'button';
        delBtn.className = 'btn delete';
        delBtn.textContent = 'Delete';
        delBtn.setAttribute('aria-label', 'Delete entry: ' + entry.task + ', ' + entry.minutes + ' minutes');

        li.appendChild(spanText);
        li.appendChild(spanMin);
        li.appendChild(delBtn);
        entriesList.appendChild(li);
      });
    }
    updateSummary();
  }

  // Update total and longest
  function updateSummary() {
    const total = entries.reduce((sum, e) => sum + e.minutes, 0);
    const longest = entries.reduce((max, e) => Math.max(max, e.minutes), 0);
    totalEl.textContent = total;
    longestEl.textContent = longest + ' min';
  }

  // Add entry
  function addEntry(task, minutes) {
    entries.push({ id: generateId(), task: task.trim(), minutes });
    saveEntries();
    render();
  }

  // Delete entry by id
  function deleteEntry(id) {
    entries = entries.filter(e => e.id !== id);
    saveEntries();
    render();
  }

  // Event: form submit
  form.addEventListener('submit', function(e) {
    e.preventDefault();
    const task = taskInput.value.trim();
    const minutes = parseInt(minutesInput.value, 10);
    if (!task || isNaN(minutes) || minutes < 1) {
      // Basic validation; required/min attributes handle most cases
      return;
    }
    addEntry(task, minutes);
    form.reset();
    taskInput.focus();
  });

  // Event: delete button click (delegation)
  entriesList.addEventListener('click', function(e) {
    const btn = e.target.closest('.btn.delete');
    if (!btn) return;
    const li = btn.closest('.entry-item');
    if (li && li.dataset.id) {
      deleteEntry(li.dataset.id);
    }
  });

  // Initialize
  loadEntries();
  render();
})();
